head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.mktTpCd = "1"; // 거래시장구분 1= 유가, 2=코스닥

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — setCode, listSync 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let vCurDate = $c.date.getServerDateTime("yyyyMMdd");
        let vEdate =  $c.date.addDate(vCurDate, 60);
        ica_EDate.setValue(vEdate);
        $c.data.comboCbDataSetPeriod(sbx_PeriodTp);

        ica_SDate.setValue("19000101");

        await scwin.setCode();
        await scwin.listSync();

        // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
        $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05002.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @event
 * @name scwin.btn_CoCdSearch_onclick
 * @description :scwin.btn_CoCdSearch_onclick
 * @returns {void}
 * @hidden N
 */
scwin.btn_CoCdSearch_onclick = function(e) {
    try {
        // fn_PopFindExamCorp(getObjectValue(rdo_SECUGRP_ID));
        scwin.popFindExamCorp(rdo_SECUGRP_ID.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_CoCdSearch_onclick" });
    }
};

/**
 * @method
 * @Method
 * @name scwin.btn_Search_onclick
 * @description :scwin.btn_Search_onclick
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    try {
        // 날짜 포맷 검증 추가
        await $c.date.compareFromToDate(ica_SDate, ica_EDate, ["조회 시작일자", "조회 종료일자"], "yyyyMMdd");

        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05002.btn_Search_onclick" });
    }
};

/**
 * @method
 * @Method
 * @name scwin.btn_Excel_onclick
 * @description :엑셀다운
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        if (grd_List.getRowCount() <= 0) {
            $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }
        $c.data.downloadGridViewExcel(grd_List, {fileName: "예비심사(유)", sheetName: "sheet1"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 신규 — 「신규」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function(e) {
    try {
        if (sbx_NEW_SECUGRP_ID.getValue() === "") {
            $c.win.alert("신규등록할 [유가증권]을 선택하세요.");

            sbx_NEW_SECUGRP_ID.focus();
            return;
        } else {
            scwin.openDetail("","C");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_New_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 콜백(레거시 Gauce 이벤트 — 현재 통신 오류 알림은 $c.sbm 공통이 담당)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadError = function() {
    try {
        $c.win.alert + $c.data.getMessage(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        FillGridHeaderTotalCnt(rowcount, spn_page);

        CloseWin(rowcount, grd_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        // if (colid=='COM_NM'){
        scwin.openDetail(row);
        // }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_oncelldblclick
 * @description 그리드 더블 클릭
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        const pRow = dlt_prelistingKospiRes.getRowJSON(rowIndex);
        scwin.openDetail(pRow,"U");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function(e) {
    try {
        popUpCalendar2(ica_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function(e) {
    try {
        popUpCalendar2(ica_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name acb_ISUR_CD_onblur
 * @description acb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.acb_ISUR_CD_onblur = function() {
    try {
        if (acb_ISUR_CD.getValue() === "") {
            ibx_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.acb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name sbx_PeriodTp_OnSelChange
 * @description sbx_PeriodTp 선택 변경 처리
 * @returns {void}
 * @hidden N
 */
scwin.sbx_PeriodTp_OnSelChange = function() {
    try {
        let vTp = sbx_PeriodTp.ValueOfIndex("VALUE", sbx_PeriodTp.Index);

        fn_setFromToDate(vTp, ica_SDate, ica_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.sbx_PeriodTp_OnSelChange" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name sbx_PeriodTp_onviewchange
 * @description sbx_PeriodTp 값 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_PeriodTp_onviewchange = function (info) {
    try {
        let vTp = sbx_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, ica_SDate, ica_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05002.sbx_PeriodTp_onviewchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 코드 값을 화면에 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {

    const sbmOptions = {
        id : "sbm_listLeadcomAll",
        method: "get",
        action : "/api/listing/common/code/list-leadcom-all",
        target : "dlt_codeSelectBox=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        sbx_LeadcomMbrNo.setNodeSet("data:" + "dlt_codeSelectBox","text","value");
    }
};

/**
 * @method
 * @func
 * @name scwin.listSync
 * @description 조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = async function() {

    dma_searchReq.set("secugrpId",rdo_SECUGRP_ID.getValue());
    dma_searchReq.set("listLmCdIdx",sbx_ListLMCd.getSelectedIndex());
    dma_searchReq.set("listLmCd",sbx_ListLMCd.getValue());
    dma_searchReq.set("isurCd",ibx_isur_CD.getValue());
    dma_searchReq.set("leadcomMbrNo",sbx_LeadcomMbrNo.getValue());
    dma_searchReq.set("strDate",ica_SDate.getValue());
    dma_searchReq.set("endDate",ica_EDate.getValue());
    dma_searchReq.set("dateType",rdo_DateType.getValue());

    const sbmOptions = {
        id : "sbm_prelistingKospi",
        action : "/api/listing/lstproc/stock/prelisting-kospi/select-list",
        method : "get",
        ref : "dma_searchReq",
        target : "dlt_prelistingKospiRes=body",
        gridview : "grd_List",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {
        spn_page.setValue(grd_List.getRowCount());
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description 부모 화면(팝업 호출원)으로 돌려줄 파라미터 배열을 만든다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = getObjectValue(acb_ISUR_CD); // 코드값을 포함할 컨트롤

    arrPar[1] = getObjectValue(ibx_COM_NM); // 명칭값을 포함할 컨트롤

    arrPar[2] = getObjectValue(rdo_SECUGRP_ID);
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SER;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description 팝업이 돌려준 파라미터 배열을 화면 입력값에 반영한다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    acb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    ibx_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name setBzProcsNo
 * @description 업무처리번호를 화면 상태값에 설정한다.
 * @param {Object} obj 객체
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {

    scwin.clickBzProcsNo = dts_List.NameString(obj, "BZ_PROCS_NO");
    // $c.win.alert("fn_setBzProcsNo():"+clickBzProcsNo);
};

/**
 * @method
 * @name getBzProcsNo
 * @description 현재 업무처리번호를 반환한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name openDetail
 * @description 상세 팝업
 * @param {Number} row 행 인덱스
 * @param {*} disPlayFlag disPlayFlag
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row,disPlayFlag) {
    // if (disPlayFlag === "U" ) { //그리드에서 선택시
    //     //fn_setBzProcsNo(row);
    //     secugrpId = dts_List.NameString(row, 'SECUGRP_ID');
    // } else { //신규버튼 선택시
    //     scwin.clickBzProcsNo = ""; //초기화
    //     secugrpId = sbx_NEW_SECUGRP_ID.getValue();
    // }
    let secuGrpNm = "";
    if(disPlayFlag === "C") {
        secuGrpNm = sbx_NEW_SECUGRP_ID.getText();
    } else {
        secuGrpNm = row.secugrpNm;
    }
    // if ( secugrpId == SECUGRP_ID_DR || secugrpId == SECUGRP_ID_FS ) {
    // 	hight = "830";
    // 	yPoint = "0";
    // }
    // $c.win.alert("[hight]"+hight);

    // frame.CreateDialogFrame("DLG_PREEXAM","/lstproc/ULDSTF05003.gfm", fn_getSecuGrpNm(secugrpId)+" 예비심사관리", 100,  yPoint, 1030, hight, "window");

    const url = "/ui/lstproc/ULDSTF05003.xml";
    const popTitle =  secuGrpNm+"예비심사관리";

    const opts = {
        id: "ULDSTF05003",
        popupName: popTitle,
        width: 1400,
        height: 1500,
        frameModal: "top",
        mktTpCd: scwin.mktTpCd,
    };

    let popData = "";

    if(disPlayFlag !== "C") {
        popData = {
        ... row,
        "disFlag" : disPlayFlag 
        }
        ;
    }
    $c.win.openPopup(url, opts, popData);

};

/**
 * @method
 * @name excelDown
 * @description 함수명 : fn_ExcelDown() 설명 : 정보를 excel로 다운 받는다
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (dts_List.countrow > 0) {
        // 엑셀 로그

        doLogSave("ULDSTF05003.xml", SCREN_PROCS_TP_CD_07);

        grd_List.GridToExcel("예비심사리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @Method
 * @name scwin.btn_CoCdSearch_onclic
 * @description :법인검색팝업호출
 * @returns {void}
 * @hidden N
 */
scwin.popFindExamCorp = async function(val) {
    let url = "/ui/lst/common/ULDSTF05011.xml";
    let popTitle = "법인 선택";

    const opts = {
        id: "ULDSTF05011",
        popupName: popTitle,
        width: 900,
        height: 700,
        frameModal: "top",
    };

    const popupData = {
        "secugrpId" : val,  
        "strTpCd": "KSP_EXEM"

    }
    const res = await $c.win.openPopup(url, opts, popupData);

    ibx_isur_CD.setValue(res.isurCd) ; // 법인코드
    ibx_COM_NM.setValue(res.comNm) ; // 법인명

};

/**
 * @method
 * @name setParam
 * @description 화면 전달 파라미터를 설정한다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function(row) {

}
